class Manager:
    def __enter__(self):
        return 7
    def __exit__(self, *args):
        return False


def main():
    with Manager() as value:
        print(value)


if __name__ == "__main__":
    main()

class Manager:
    def __enter__(self):
        return self
    def __exit__(self, *args):
        print("exit")
        return False


def main():
    try:
        with Manager():
            raise ValueError()
    except ValueError:
        print("caught")


if __name__ == "__main__":
    main()

class Manager:
    def __enter__(self):
        return self
    def __exit__(self, *args):
        return True


def main():
    with Manager():
        raise ValueError()
    print("after")


if __name__ == "__main__":
    main()
